void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85; // make rephase more frequent
    rephase_limit += 4096; // smaller increment than original

    int choice = rand() % 100;
    if (choice < 40) {
        // use current trail values as phase
        for (int i = 1; i <= vars; i++) {
            saved[i] = value[i];
        }
    } else if (choice < 70) {
        // invert current trail values
        for (int i = 1; i <= vars; i++) {
            saved[i] = -value[i];
        }
    } else if (choice < 90) {
        // use local best phase
        for (int i = 1; i <= vars; i++) {
            saved[i] = local_best[i];
        }
    } else {
        // random phase
        for (int i = 1; i <= vars; i++) {
            saved[i] = rand() % 2 ? 1 : -1;
        }
    }
}
